// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz an arbitrary bytes calldata seed so the fuzzer can produce inputs
    // that exercise different calldata encodings. The general rule: calling
    // the external function `version()` (selector 0x54fd4d50) should return
    // the UTF-8 string "1.0.0" for the correct contract; the mutant returns
    // a different string for some inputs. We use a low-level staticcall with
    // the selector placed at the start of calldata to observe the returned
    // raw bytes and compare them against the expected encoding for "1.0.0".
    function testFuzz_property(bytes memory seed) public {
        // keep domain wide; no tight constraints
        // prepare calldata: place the selector for version() at start
        bytes4 sel = bytes4(keccak256("version()"));
        bytes memory callData = abi.encodePacked(sel, seed);

        // perform a staticcall to c with this calldata
        (bool ok, bytes memory ret) = address(c).staticcall(callData);

        // If the call succeeded, the correct contract always returns the ABI-encoded string "1.0.0".
        // ABI encoding of a single string return is: offset (32) then length then data padded.
        // We construct the expected encoding once and compare raw bytes.
        bytes memory expected = abi.encode("1.0.0");

        // The universal property to assert: whenever the call succeeds, the returned data equals abi.encode("1.0.0").
        // The mutant that returns "1.0.1" will for at least some fuzzed seed produce ok==true and ret!=expected,
        // causing this assertion to fail.
        if (ok) {
            assertTrue(keccak256(ret) == keccak256(expected));
        } else {
            // If the call reverted, the reference contract never reverts on version(),
            // so ok should always be true; keep assertion that ok is true as part of the same condition
            // We coalesce into a single assertTrue by encoding the implication: ok ==> ret==expected
            // But since we must have exactly one assertTrue, move the condition here.
            // Represent (ok implies ret==expected) as (!ok) || (ret==expected)
            // However we already handled ok==true branch above, so simply assertFalse here to fail if !ok.
            // To keep a single assertTrue overall, we instead compute the combined boolean and assert it.
            // (This branch won't run because of the if, but we need a single assertTrue in the function scope.)
        }

        // Single assertion covering both cases: if call succeeded, returned bytes equal expected; if call failed, that's a violation
        bool propHolds = ok && (keccak256(ret) == keccak256(expected));
        assertTrue(propHolds);
    }
}

