pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param is an address to call version from (prank), ensuring we don't hard-code caller
    function testFuzz_property(address caller) public {
        // keep wide domain: disallow zero address just to avoid degenerate pranks
        if (caller == address(0)) caller = address(1);

        // call version() from arbitrary caller to exercise external call path
        bool ok;
        string memory v;
        vm.prank(caller);
        try c.version() returns (string memory s) {
            ok = true;
            v = s;
        } catch {
            ok = false;
            v = "";
        }

        // The reference contract always returns a string that does NOT contain "+mutant" and does not revert.
        // Single assertion: ok is true and returned string does not contain the substring "+mutant".
        // We observe c only through its external version() getter.
        bytes memory vb = bytes(v);
        bool containsMutant = false;
        for (uint i = 0; i + 7 <= vb.length; i++) { // length of "+mutant" is 7
            // check substring of length 7
            bool match = true;
            bytes1[7] memory target = [bytes1("+"), bytes1("m"), bytes1("u"), bytes1("t"), bytes1("a"), bytes1("n"), bytes1("t")];
            for (uint j = 0; j < 7; j++) {
                if (vb[i + j] != target[j]) { match = false; break; }
            }
            if (match) { containsMutant = true; break; }
        }

        assertTrue(ok && !containsMutant);
    }
}

