pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address and the number to set; the depositor account is a known constant in C
    function testFuzz_property(address caller, uint64 newNumber) public {
        // keep caller as a wide domain but avoid zero so we can exercise the normal depositor behavior when caller==DEPOSITOR_ACCOUNT
        // We do not constrain caller to be non-zero because the property must hold for all inputs; still allow zero as fuzzer input
        // Arrange: fund caller so vm.prank can send transactions (not strictly necessary for non-payable calls but harmless)
        vm.deal(caller, 1 ether);

        // The depositor account is a compile-time constant in the contract; reproduce it here
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

        // Act: if the fuzzed caller equals the depositor, call as that depositor and set number to newNumber
        bool ok;
        if (caller == depositor) {
            vm.prank(caller);
            // call should succeed on the correct contract and update number to newNumber
            try c.setL1BlockValues(newNumber, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) {
                ok = true;
            } catch {
                ok = false;
            }
            // Assert: when the call is made by the real depositor, it must succeed and the stored number must equal the provided value
            // This single assertion is true for the reference contract for all inputs; the mutant that restricts to address(0) will fail for caller==depositor
            assertTrue(ok && c.number() == newNumber);
        } else {
            // If caller is not the depositor, we still perform a call to ensure we don't constrain fuzzing
            vm.prank(caller);
            try c.setL1BlockValues(newNumber, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) {
                ok = true;
            } catch {
                ok = false;
            }

            // For non-depositor callers the reference contract reverts; assert that number was NOT changed to newNumber by this non-depositor call.
            // If the call unexpectedly succeeded and changed the number, that would violate the general rule.
            // We allow either revert (ok==false) or success without changing number (ok==true && c.number()!=newNumber).
            assertTrue(!ok || c.number() != newNumber);
        }
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // single public entry performing the sequence and final assertion
    function check(address caller, uint64 newNumber, uint64 newTimestamp, uint256 newBasefee, bytes32 newHash, uint64 newSequenceNumber, bytes32 newBatcherHash, uint256 newL1FeeOverhead, uint256 newL1FeeScalar) external {
        // Preconditions: caller must not be the depositor defined in C
        // read depositor constant via storage slot by calling set with depositor check? Not possible; instead require caller != c.DEPOSITOR_ACCOUNT()
        require(caller != c.DEPOSITOR_ACCOUNT(), "caller must be non-depositor for this test");

        // Record prior timestamp (initially zero unless set by depositor earlier)
        uint64 priorTimestamp = c.timestamp();

        // Try to call setL1BlockValues as the provided caller by performing a low-level call
        // We cannot change msg.sender in Solidity directly; instead encode the calldata and use address(c).call from this contract
        // So simulate the call originating from 'caller' by requiring that this contract is approved to be that caller is not possible.
        // Instead, we drive with this contract as sender: the crucial distinction is whether onlyDepositor restricts to a specific hard-coded address; since caller != depositor, this contract must be different from depositor.
        // Ensure this contract is not the depositor
        require(address(this) != c.DEPOSITOR_ACCOUNT(), "test contract must not be the depositor");

        // Perform the state-changing call: since we must interact only through c, call the function directly (this contract will be msg.sender)
        c.setL1BlockValues(newNumber, newTimestamp, newBasefee, newHash, newSequenceNumber, newBatcherHash, newL1FeeOverhead, newL1FeeScalar);

        // After the call, read the timestamp
        uint64 afterTimestamp = c.timestamp();

        // On the original contract P this contract is not the depositor, so the setL1BlockValues should have been rejected by onlyDepositor and timestamp unchanged.
        // On mutant M the check is removed and timestamp would equal newTimestamp. So assert that timestamp did NOT become newTimestamp.
        assert(afterTimestamp != newTimestamp ? true : (afterTimestamp == priorTimestamp));
    }

    // Fallbacks allowed but unused
    receive() external payable {}
    fallback() external payable {}
}

