    // depositor can set the hash, so for a non-depositor caller the stored hash must remain unchanged.

    // We implement the check for the distinguishing behavior by taking an initial hash seed,
    // then calling setL1BlockValues with a new hash from THIS contract (caller). We require that
    // the initial hash is different from the new hash to make the effect observable.

    function test_setL1BlockValues_changes_hash_only_for_depositor(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hashNew,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Read initial hash
        bytes32 h0 = c.hash();

        // Ensure the new hash is different so change is detectable
        require(h0 != _hashNew, "choose _hashNew different from existing hash");

        // Call the state-changing function as this caller (not the depositor)
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hashNew,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        // Read resulting hash
        bytes32 h1 = c.hash();

        // On the original contract P, only the depositor can change values, so since this caller
        // is not the depositor (the test is run by an arbitrary account), the stored hash must remain unchanged.
        // This single assert distinguishes P (holds) from M (mutant removed the check and would set the hash).
        assert(h1 == h0);
    }

    // fallback and receive allowed but unused
    receive() external payable {}
    fallback() external payable {}
}
